-- Edits suggested to any knowledge base page, by any agent, for a person to accept wholly or in part
-- or dismiss with a reason, reviewed on the page itself. The company doc's proposals become the
-- suggestions to its sections' pages, nothing lost. See docs/knowledge.md, Pages, Suggestions.

CREATE TABLE page_suggestions (
    -- Generated by the API (UUIDv7), so suggestions order as they were made. A proposal moved here
    -- keeps its id, which its section's history names.
    id UUID PRIMARY KEY,
    page_id UUID NOT NULL REFERENCES pages (id) ON DELETE CASCADE,
    -- The version the suggestion was written from, and that version's text, which its edits were
    -- applied to and which accepting merges from. The text is kept beside the number because the
    -- merge needs exactly what the edits saw, and reading it back through the version would make
    -- every pending suggestion's review a join on the page's history.
    base_version INTEGER NOT NULL,
    base_body TEXT NOT NULL CHECK (char_length(base_body) <= 100000),
    -- The page's text as the suggestion would leave it.
    body TEXT NOT NULL CHECK (char_length(body) <= 100000),
    -- Why, and where it was read: a quote and its source.
    reason TEXT NOT NULL CHECK (char_length(reason) BETWEEN 1 AND 2000),
    quote TEXT CHECK (char_length(quote) BETWEEN 1 AND 2000),
    source TEXT CHECK (char_length(source) BETWEEN 1 AND 500),
    -- The timeline record the company doc's review read it in, while that record exists. A record
    -- belongs to its owner, so the page shows the quote and source rather than opening the record.
    timeline_record_id UUID REFERENCES timeline_records (id) ON DELETE SET NULL,
    -- The company doc review's run that suggested it, while the run exists.
    workflow_run_id UUID REFERENCES workflow_runs (id) ON DELETE SET NULL,
    state TEXT NOT NULL DEFAULT 'pending' CHECK (state IN ('pending', 'accepted', 'dismissed')),
    -- On an accepted suggestion, the changes taken, by their place from 0 among the suggestion's
    -- changes (crate::models::page_suggestion::changes); NULL when every one was taken.
    accepted_changes INTEGER[] CHECK (
        cardinality(accepted_changes) >= 1 AND array_position(accepted_changes, NULL) IS NULL
    ),
    -- Why it was dismissed. Required of a person dismissing one; a proposal rejected before
    -- reasons were asked for has none.
    dismissal_reason TEXT CHECK (char_length(dismissal_reason) BETWEEN 1 AND 2000),
    decided_by UUID REFERENCES users (id),
    decided_at TIMESTAMPTZ,
    -- Who suggested it, as every write of a page records its author: a person, for their MCP
    -- client or a session they started, or the machine user of Elysia or a Project Manager.
    created_by UUID NOT NULL REFERENCES users (id),
    -- The agent acting for them, as page_versions records it. NULL for Elysia and her review.
    agent TEXT CHECK (
        agent ~ '^(mcp:[^[:space:]]{1,255}|session:[0-9]{1,18}|project_manager:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$'
    ),
    -- What an MCP client called itself. A label only; `agent` is the identity.
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    created_at TIMESTAMPTZ NOT NULL,

    FOREIGN KEY (page_id, base_version) REFERENCES page_versions (page_id, version),
    CONSTRAINT page_suggestions_changes_something CHECK (body <> base_body),
    CONSTRAINT page_suggestions_decided_once CHECK (
        (state = 'pending') = (decided_by IS NULL) AND (decided_by IS NULL) = (decided_at IS NULL)
    ),
    CONSTRAINT page_suggestions_accepted_changes_when_accepted CHECK (
        accepted_changes IS NULL OR state = 'accepted'
    ),
    CONSTRAINT page_suggestions_dismissal_reason_when_dismissed CHECK (
        dismissal_reason IS NULL OR state = 'dismissed'
    ),
    CONSTRAINT page_suggestions_agent_named_with_its_agent CHECK (
        agent IS NOT NULL OR agent_name IS NULL
    )
);

-- The same change is pending once on a page, however many times it is suggested: a review step that
-- runs again, or two agents that read the same message, meet the suggestion already there. Indexed
-- by the text's md5, which Postgres marks immutable, since a page's text can outgrow a btree entry;
-- it only tells suggestions apart, so collisions need no resistance to attack.
CREATE UNIQUE INDEX page_suggestions_pending_once
    ON page_suggestions (page_id, md5(body))
    WHERE state = 'pending';

-- What waits on each page, in the order it was suggested: the page's Suggestions tab, the counts the
-- tree and search show, and the inbox item.
CREATE INDEX page_suggestions_pending ON page_suggestions (page_id, id) WHERE state = 'pending';

-- Every page's suggestions by state, newest last: the company doc's review reads the latest dismissed.
CREATE INDEX page_suggestions_by_state ON page_suggestions (state, id);

-- The one inbox item per page that asks a person to review its suggestions, kept up to date with how
-- many wait and resolved once none are left. A page has at most one at a time; when its person
-- resolved or dismissed it by hand, the next suggestion raises a new one here.
CREATE TABLE page_suggestion_items (
    page_id UUID PRIMARY KEY REFERENCES pages (id) ON DELETE CASCADE,
    action_item_id UUID NOT NULL REFERENCES action_items (id) ON DELETE CASCADE,
    -- The system user: Elysium raises it, whoever suggested.
    created_by UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

SELECT diesel_manage_updated_at('page_suggestion_items');

-- Every proposal to the company doc, pending and decided, becomes a suggestion to its section's page.
-- Each names the version its section read when it was made: the newest one whose text is the text it
-- was made against and that was published by then, or any with that text when the clocks disagree,
-- or the version published by then when none holds it exactly. The text it was made against is kept
-- either way, so the merge is unchanged.
INSERT INTO page_suggestions (
    id, page_id, base_version, base_body, body, reason, quote, source, timeline_record_id,
    workflow_run_id, state, dismissal_reason, decided_by, decided_at, created_by, agent, agent_name,
    created_at
)
SELECT proposals.id, sections.page_id,
       COALESCE(
           (SELECT max(versions.version) FROM page_versions AS versions
            WHERE versions.page_id = sections.page_id
              AND versions.body = proposals.base_content
              AND versions.created_at <= proposals.created_at),
           (SELECT max(versions.version) FROM page_versions AS versions
            WHERE versions.page_id = sections.page_id AND versions.body = proposals.base_content),
           (SELECT max(versions.version) FROM page_versions AS versions
            WHERE versions.page_id = sections.page_id
              AND versions.created_at <= proposals.created_at),
           1
       ),
       proposals.base_content, proposals.content, proposals.reason, proposals.quote,
       proposals.source, proposals.timeline_record_id, proposals.workflow_run_id,
       CASE proposals.state
           WHEN 'approved' THEN 'accepted'
           WHEN 'rejected' THEN 'dismissed'
           ELSE 'pending'
       END,
       NULL, proposals.decided_by, proposals.decided_at, proposals.created_by, proposals.agent,
       proposals.agent_name, proposals.created_at
FROM company_doc_proposals AS proposals
JOIN (VALUES
    ('company', '00000000-0000-0000-0002-000000000001'::uuid),
    ('leadership', '00000000-0000-0000-0002-000000000002'::uuid),
    ('people', '00000000-0000-0000-0002-000000000003'::uuid),
    ('stakeholders', '00000000-0000-0000-0002-000000000004'::uuid),
    ('products', '00000000-0000-0000-0002-000000000005'::uuid),
    ('projects', '00000000-0000-0000-0002-000000000006'::uuid),
    ('glossary', '00000000-0000-0000-0002-000000000007'::uuid)
) AS sections (section, page_id) ON sections.section = proposals.section;

-- A version an applied proposal wrote names it as the suggestion it now is.
UPDATE page_events
SET data = (data - 'proposalId') || jsonb_build_object('suggestionId', data -> 'proposalId')
WHERE data ? 'proposalId';

DROP TABLE company_doc_proposals;
